mapper.select:
SELECT sum(wsri.quantity) quantity, wsri.material_name FROM wms_storage_receipt_info wsri LEFT JOIN wms_storage_receipt wsr ON wsr.id = wsri.storage_receipt_id WHERE wsr.del_flag = 0 AND wsr.`status` != 5 AND wsr.type = #{typeId} AND wsr.affirm_time BETWEEN #{startTime} AND #{endTime} AND wsri.material_name in
#{name}
GROUP BY material_name

SELECT sum(a.quantity) FROM wms_storage_receipt_info a JOIN wms_storage_receipt b ON b.id = a.storage_receipt_id where b.type = '1600405739121573888' and a.material_id in
#{id}
and b.come_time between #{startTime} and #{endTime}
